config.script:
# One handler persists every mutation (create/edit/delete/move/resize,
# cross-row reassign, recurring series vs occurrence) into the session store.
ev = event.event
action = event.action
scope = getattr(event, "scope", None)
seriesId = getattr(event, "seriesId", None)
occDate = getattr(event, "occurrenceDate", None)
events = [dict(e) for e in self.session.custom.demo.maint]
recurring = [dict(e) for e in self.session.custom.demo.maintRecurring]

def idx_of(lst, eid):
	for i in range(len(lst)):
		if lst[i].get("id") == eid:
			return i
	return -1

def row_from(e):
	row = {"id": e.id,         "title": getattr(e, "title", ""), "start": getattr(e, "start", ""),
		"end": getattr(e, "end", ""), "category": getattr(e, "category", ""),
		"description": getattr(e, "description", ""),
		"allDay": bool(getattr(e, "allDay", False))}
	for k in ("color", "status", "display"):
		val = getattr(e, k, "")
		if val:
			row[k] = val
	rr = getattr(e, "rrule", None)
	if rr is not None:
		row["rrule"] = rr
	return row

def upsert(lst, row, merge=False):
	i = idx_of(lst, row.get("id"))
	if i >= 0:
		if merge:
			kept = dict(lst[i])
			kept.update(row)
			lst[i] = kept
		else:
			lst[i] = row
	else:
		lst.append(row)

def add_exdate(sid, dte):
	for lst in (events, recurring):
		i = idx_of(lst, sid)
		if i >= 0:
			base = dict(lst[i])
			rr = dict(base.get("rrule") or {})
			ex = list(rr.get("exdate") or [])
			if dte not in ex:
				ex.append(dte)
			rr["exdate"] = ex
			base["rrule"] = rr
			lst[i] = base
			return

if scope == "occurrence":
	add_exdate(seriesId, occDate)
	if action == "delete":
		events = [e for e in events if e.get("id") != ev.id]
	else:
		upsert(events, row_from(ev))
elif scope == "series":
	if action == "delete":
		events = [e for e in events if e.get("id") != seriesId]
		recurring = [e for e in recurring if e.get("id") != seriesId]
	else:
		if idx_of(recurring, seriesId) >= 0:
			upsert(recurring, row_from(ev))
		else:
			upsert(events, row_from(ev))
else:
	if action == "delete":
		events = [e for e in events if e.get("id") != ev.id]
	else:
		upsert(events, row_from(ev), merge=True)

self.session.custom.demo.maint = events
self.session.custom.demo.maintRecurring = recurring
